import { registerPatient } from "../slices/patientSlice";

/**
 * Fetch a Patient by ID
 * - Checks Redux store first
 * - Fetches from FHIR server if missing
 * - Registers into Redux
 */
export const fetchPatient = async (patientId, fhirClient, getState, dispatch) => {
    if (!patientId || !fhirClient) return null;

    // Check Redux store
    const cached = getState().patients?.[patientId];
    if (cached) {
        // console.log(`🧠 Patient ${patientId} served from cache`);
        return cached;
    }

    try {
        // console.log(`🌐 Fetching Patient/${patientId} from FHIR`);
        const fetched = await fhirClient.request(`Patient/${patientId}`);

        if (!fetched?.resourceType === "Patient") {
            console.warn("⚠️ Unexpected patient response:", fetched);
            return null;
        }

        dispatch(registerPatient(fetched));
        return fetched;

    } catch (err) {
        console.error("❌ Failed to fetch patient:", err);
        return null;
    }
};

/**
 * Fetch a patient given a FHIR reference string
 * e.g. "Patient/123" or "Patient/123/_history/4"
 */
export const fetchPatientByReference = async (ref, fhirClient, getState, dispatch) => {
    if (!ref || typeof ref !== "string") {
        console.warn("⚠️ Invalid patient reference (not a string):", ref);
        return null;
    }

    if (!ref.startsWith("Patient/")) {
        console.warn("⚠️ Reference is not a Patient:", ref);
        return null;
    }

    // Extract ID safely even if versioned
    // "Patient/123" → "123"
    // "Patient/123/_history/5" → "123"
    const parts = ref.split("/");
    const patientId = parts[1];

    if (!patientId || patientId === "undefined" || patientId === "null") {
        console.warn("⚠️ Could not extract valid patient ID from reference:", ref);
        return null;
    }

    return fetchPatient(patientId, fhirClient, getState, dispatch);
};
