/**
 * Checks if a Communication message is hydrated in Redux.
 * @param {Object} message - The Communication object (must have an `id`).
 * @param {Object} byId - The Redux slice containing messages keyed by ID.
 * @returns {boolean} - True if hydrated, false otherwise.
 */
export function isHydrated(message, byId) {
    if (!message?.id || !byId?.[message.id]) return false;
    return !!byId[message.id]?.meta?.hydrated;
};


export function hasBeenReadByCurrentUser(comm, userId) {
    if (!comm || !userId) return false;

    const normalizedUserId = userId.split("/")?.pop(); // e.g., "1234" from "Practitioner/1234"

    // ✅ If the sender is the current user, it's already read
    const senderRef = comm.sender?.reference;
    const normalizedSenderId = senderRef?.split("/")?.pop();
    if (normalizedSenderId === normalizedUserId) return true;

    // ✅ Otherwise, check for read receipts
    const receipts = comm.extension?.filter(
        (ext) => ext.url === "http://endpointhealth.ca/fhir/StructureDefinition/read-receipt"
    ) || [];

    return receipts.some((receipt) => {
        const userRef = receipt.extension?.find(e => e.url === "user")?.valueReference?.reference;
        const readAt = receipt.extension?.find(e => e.url === "readAt")?.valueDateTime;
        const normalizedRefId = userRef?.split("/")?.pop();

        return normalizedUserId === normalizedRefId && !!readAt;
    });
}



export function promoteMessageFromNewToMain(message, dispatch) {
    dispatch(addMessage(message)); // adds to messages.byId
    dispatch(acknowledgeNewMessage(message.id)); // removes from newMessages
};

//for updating read receipts on the right reducer.
export function dispatchMessageUpdate(message, dispatch, getState) {
    const state = getState();
    const inNewMessages = !!state.messages.newMessages.byId[message.id];

    if (inNewMessages) {
        dispatch(acknowledgeNewMessage(message.id));
    }

    dispatch(addMessage(message));
};

export function isSelfMessage(message, providerId) {
    if (!message || !message.sender || !providerId) return false;

    // FHIR references usually look like "Practitioner/123"
    const senderRef = message.sender.reference || "";
    return senderRef === `Practitioner/${providerId}`;
};

