/**
 * Extract attachment and referenced resources from a FHIR Communication resource.
 * @param {Object} message - FHIR Communication resource.
 * @returns {Array} - Array of attachment objects:
 *                    { type: "attachment" | "reference", url, title, contentType }
 */
/**
 * Extracts attachments from a FHIR Communication resource.
 * Returns both payload attachments and about references.
 */
export function getMessageAttachments(message) {
    //console.log("Getting message attachments...........");
    if (!message) return [];

    const attachments = [];

    const aboutRefs = new Set(
        Array.isArray(message.about)
            ? message.about.map(ref => ref.reference)
            : []
    );

    // Process payload
    if (Array.isArray(message.payload)) {
        message.payload.forEach((entry, idx) => {
            if (entry.contentAttachment) {
                //console.log(entry);
                // Extract the resource ID from the URL
                const urlId = entry.contentAttachment.url?.split('/').pop();
                if (
                    aboutRefs.has(`Observation/${urlId}`) || aboutRefs.has(`DiagnosticReport/${urlId}`)
                ) {
                    return;
                }
                attachments.push({
                    type: 'attachment',
                    ...entry.contentAttachment
                });
            } else if (entry.contentReference?.reference) {
                attachments.push({
                    type: 'reference',
                    url: entry.contentReference.reference
                });
            }
        });
    }

    // Add about references
    if (Array.isArray(message.about)) {
        message.about.forEach((ref, idx) => {
            if (ref.reference) {
                attachments.push({
                    type: 'reference',
                    url: ref.reference
                });
            }
        });
    }

    //console.log("getMessageAttachments: final attachments", attachments);
    return attachments;
}


/**
 * Builds a FHIR AuditEvent agent object from a contextProvider.
 * @param {Object} contextProvider - The Practitioner resource or null.
 * @returns {Object} FHIR AuditEvent agent object.
 */
export function buildAgentFromContextProvider(contextProvider) {
    if (contextProvider) {
        return {
            who: {
                reference: `Practitioner/${contextProvider.id}`,
                display:
                    contextProvider.name?.[0]?.text ||
                    `${contextProvider.name?.[0]?.given?.join(" ")} ${contextProvider.name?.[0]?.family}` ||
                    "Unknown"
            },
            requestor: true
        };
    }
    return {
        who: { reference: "Practitioner/unknown", display: "Unknown" },
        requestor: true
    };
}

/**
 * Builds a FHIR AuditEvent entity object from a contextPatient.
 * @param {Object} contextPatient - The Patient resource or null.
 * @returns {Object} FHIR AuditEvent entity object.
 */
export function buildEntityFromContextPatient(contextPatient) {
    if (contextPatient) {
        return {
            what: {
                reference: `Patient/${contextPatient.id}`,
                display:
                    contextPatient.name?.[0]?.text ||
                    `${contextPatient.name?.[0]?.given?.join(" ")} ${contextPatient.name?.[0]?.family}` ||
                    "Unknown"
            },
            role: { code: "1", display: "Patient" }
        };
    }
    return {
        what: { reference: "Patient/unknown", display: "Unknown" },
        role: { code: "1", display: "Patient" }
    };
}

/**
 * Validates FHIR references for communications
 * Ensures patients are patients, practitioners are practitioners, etc.
 * @param {Array} messages - Array of Communication resources
 * @param {object} fhirClient - FHIR client instance
 * @param {function} getState - Redux getState
 * @param {function} dispatch - Redux dispatch
 * @returns {Promise<Array>} - Array of validated messages
 */
export async function validateCommunications(messages, fhirClient, getState, dispatch) {
    console.log("Validating communications...");
    const validated = [];

    for (const comm of messages) {
        console.log(`Validating communication ${comm.id}...`);
        let isValid = true;

        // 1. Validate patient (subject)
        const subjectRef = comm.subject?.reference;
        if (subjectRef?.startsWith("Patient/")) {
            const patientId = subjectRef.split("/")[1];
            let patient = patientId ? getState().patients?.[patientId] : null;
            if (!patient) {
                patient = await fetchPatientByReference(subjectRef, fhirClient, getState, dispatch);
            }
            if (!patient || patient.resourceType !== "Patient") {
                console.log(`Invalid patient reference for comm ${comm.id}:`, subjectRef);
                isValid = false;
            }
        }

        // 2. Validate sender
        const senderRef = comm.sender?.reference;
        if (senderRef?.startsWith("Practitioner/")) {
            const senderId = senderRef.split("/")[1];
            let sender = senderId ? getState().providers?.[senderId] : null;
            if (!sender) {
                sender = await fetchProviderByReference(senderRef, fhirClient, getState, dispatch);
            }
            if (!sender || sender.resourceType !== "Practitioner") {
                console.log(`Invalid practitioner reference for comm ${comm.id}:`, senderRef);
                isValid = false;
            }
        } else if (senderRef?.startsWith("Patient/")) {
            const patientId = senderRef.split("/")[1];
            let patient = patientId ? getState().patients?.[patientId] : null;
            if (!patient) {
                patient = await fetchPatientByReference(senderRef, fhirClient, getState, dispatch);
            }
            if (!patient || patient.resourceType !== "Patient") {
                console.log(`Invalid sender patient reference for comm ${comm.id}:`, senderRef);
                isValid = false;
            }
        }

        if (isValid) validated.push(comm);
    }
    
    console.log(`Validated ${validated.length} out of ${messages.length} communications.`);
    console.log("Validated communications:", validated);
    let sanitized = sanitizeCommunications(validated);
    //return validated;
    return sanitized;
}

/**
 * Sanitize a single Communication resource by normalizing/removing "unknown" placeholders
 * and cleaning up invalid references so UI/filtering code can handle the resource.
 * @param {Object} comm
 * @returns {Object} sanitized communication
 */
export function sanitizeCommunication(comm) {
    
    if (!comm || typeof comm !== "object") return comm;
    // deep clone to avoid mutating original
    const c = JSON.parse(JSON.stringify(comm));

    const cleanRef = (ref) => {
        if (!ref) return null;
        if (typeof ref === "string" && ref.trim().toLowerCase() === "unknown") return null;
        return ref;
    };

    // Top-level reference fields
    if (c.sender?.reference) c.sender.reference = cleanRef(c.sender.reference);
    if (c.subject?.reference) c.subject.reference = cleanRef(c.subject.reference);
    if (c.encounter?.reference) c.encounter.reference = cleanRef(c.encounter.reference);

    // Recipients: normalize and drop invalid entries
    if (Array.isArray(c.recipient)) {
        c.recipient = c.recipient
            .map(r => ({ ...r, reference: cleanRef(r.reference) }))
            .filter(r => r && r.reference);
        if (c.recipient.length === 0) delete c.recipient;
    }

    // Priority/topic normalization
    if (typeof c.priority === "string" && c.priority.trim().toLowerCase() === "unknown") {
        delete c.priority;
    }

    if (typeof c.topic === "string" && c.topic.trim().toLowerCase() === "unknown") {
        delete c.topic;
    } else if (c.topic && typeof c.topic === "object") {
        const display = c.topic.coding?.[0]?.display;
        if (typeof display === "string" && display.trim().toLowerCase() === "unknown") {
            delete c.topic;
        }
    }

    // Sanitize extensions that are clearly placeholders (remove if they reference 'unknown')
    if (Array.isArray(c.extension)) {
        c.extension = c.extension.filter(ext => {
            if (!ext) return false;
            const ref = ext?.valueReference?.reference || ext?.reference;
            if (typeof ref === "string" && ref.trim().toLowerCase() === "unknown") return false;
            return true;
        });
        if (c.extension.length === 0) delete c.extension;
    }

    // Ensure strings that are the literal "unknown" are removed in common text fields
    if (typeof c.topic === "string" && c.topic.trim().toLowerCase() === "unknown") delete c.topic;
    if (typeof c.status === "string" && c.status.trim().toLowerCase() === "unknown") delete c.status;

    return c;
}

/**
 * Sanitize an array of Communication resources.
 * @param {Array} messages
 * @returns {Array} sanitized messages
 */
export function sanitizeCommunications(messages = []) {
    console.log("Sanitizing communications");
    console.log(messages);
    if (!Array.isArray(messages)) return messages;
    return messages.map(sanitizeCommunication);
}

