// renderUtils.js
import React from "react";
import ObservationIcon from "../assets/microscope_96.png";
import DiagnosticReportIcon from "../assets/diagnostic-report-1.png";
import DocumentIcon from "../assets/doc-ref-1.png";
import MediaIcon from "../assets/media-1.png";
import { getIconForContentType } from "./getIconForContentType";
import styles from "./renderUtils.module.css";


export const renderCommunicationAttachments = (comm = {}) => {
    const seen = {
        file: false,
        observation: false,
        document: false,
        diagnostic: false
    };

    const icons = [];

    const addIcon = (type, element) => {
        if (!seen[type]) {
            seen[type] = true;
            icons.push(
                <span key={type} style={{ marginLeft: "0.4rem" }}>
                    {element}
                </span>
            );
        }
    };

    // -----------------------------
    // Handle payload[]
    // -----------------------------
    (comm.payload || []).forEach((p) => {
        // 1) contentAttachment → FILES using helper
        if (p.contentAttachment) {
            const ct = p.contentAttachment.contentType || "";
            const title = p.contentAttachment.title || "";

            // Pass a combined string to help filename detection inside helper
            const detectString = `${ct} ${title}`.trim().toLowerCase();

            const icon = getIconForContentType(detectString, "contentAttachment");

            addIcon("file", icon);     // one generic file group (PDF, Word, etc.)
        }

        // 2) contentReference → resource icons
        if (p.contentReference?.reference) {
            const ref = p.contentReference.reference;

            if (ref.startsWith("Observation/")) {
                addIcon(
                    "observation",
                    <img
                        src={ObservationIcon}
                        alt="Observation Attachment"
                        style={{ width: 20, height: 20 }}
                    />
                );
            }

            if (ref.startsWith("DocumentReference/")) {
                addIcon(
                    "document",
                    <img
                        src={DocumentIcon}
                        alt="Document Attachment"
                        style={{ width: 20, height: 20 }}
                    />
                );
            }

            if (ref.startsWith("DiagnosticReport/")) {
                addIcon(
                    "diagnostic",
                    <img
                        src={DiagnosticReportIcon}
                        alt="Diagnostic Report Attachment"
                        style={{ width: 20, height: 20 }}
                    />
                );
            }
        }
    });

    // -----------------------------
    // Handle about[]
    // -----------------------------
    (comm.about || []).forEach((refObj) => {
        const ref = refObj.reference || "";

        if (ref.startsWith("Observation/")) {
            addIcon(
                "observation",
                <img
                    src={ObservationIcon}
                    alt="Observation Attachment"
                    style={{ width: 20, height: 20 }}
                />
            );
        }

        if (ref.startsWith("DocumentReference/")) {
            addIcon(
                "document",
                <img
                    src={DocumentIcon}
                    alt="Document Attachment"
                    style={{ width: 20, height: 20 }}
                />
            );
        }

        if (ref.startsWith("DiagnosticReport/")) {
            addIcon(
                "diagnostic",
                <img
                    src={DiagnosticReportIcon}
                    alt="Diagnostic Report Attachment"
                    style={{ width: 20, height: 20 }}
                />
            );
        }
    });

    return icons.length > 0 ? <>{icons}</> : null;
};
export const getResourceIcon = (resourceType) => {
    if (!resourceType) return null;

    const type = resourceType.toLowerCase();

    if (type === "observation") {
        return <img src={ObservationIcon} alt="Observation" className={styles.resourceIcon} />;
    }

    if (type === "documentreference") {
        return <img src={DocumentIcon} alt="Document Reference" className={styles.resourceIcon} />;
    }

    if (type === "diagnosticreport") {
        return <img src={DiagnosticReportIcon} alt="Diagnostic Report" className={styles.resourceIcon} />;
    }

    if (type === "media") {
        return <img src={MediaIcon} alt="Media" className={styles.resourceIcon} />;
    }


    return null;
};

