import { configureStore } from "@reduxjs/toolkit";

import messageReducer from "../slices/messageSlice.js";
import providerRegistryReducer from "../slices/providerRegistrySlice.js";
import patientReducer from "../slices/patientSlice.js";
import encounterReducer from "../slices/encounterSlice.js";
import configReducer from "../slices/configSlice.js";
import observationReducer from "../slices/observationSlice.js";
import documentReferenceReducer from "../slices/documentReferenceSlice.js"; 
import diagnosticReportReducer from "../slices/diagnosticReportSlice.js"; 
import organizationReducer from "../slices/organizationSlice.js"; 


export const createStore = () =>
  configureStore({
    reducer: {
      messages: messageReducer,
      providers: providerRegistryReducer,
      patients: patientReducer,
      encounters: encounterReducer,
      observations: observationReducer,
      documentReferences: documentReferenceReducer,
      diagnosticReports: diagnosticReportReducer,
      organizations: organizationReducer,
      config: configReducer,
    },
  });

export default createStore;
