import React, { useState } from "react";
import { Modal } from "react-bootstrap";
import styles from "./AttachmentList.module.css";
import { getIconForContentType } from "../utils/getIconForContentType";
import PDFViewer from "../utils/PDFViewer";

// Utility: Map MIME type to file extension
const getExtensionFromContentType = (contentType) => {
    const map = {
        "application/pdf": "pdf",
        "image/jpeg": "jpg",
        "image/png": "png",
        "image/gif": "gif",
        "image/webp": "webp",
        "image/bmp": "bmp",
        "text/plain": "txt",
        "text/html": "html",
        "application/json": "json",
        "application/xml": "xml",
        "application/msword": "doc",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx"
    };
    return map[contentType] || "dat";
};

// Download utility
const handleDownload = async (client, contentType, url, title = "document") => {
    try {
        const extension = getExtensionFromContentType(contentType);
        const filename = title.endsWith(`.${extension}`) ? title : `${title}.${extension}`;

        const response = await client.request(url, {
            headers: { Accept: contentType },
            fetchResponse: true
        });

        const blob =
            response instanceof Response
                ? await response.blob()
                : new Blob([response], { type: contentType });

        const blobUrl = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = blobUrl;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(blobUrl);
    } catch (err) {
        console.error("Download error:", err);
    }
};

// Resolve Binary URL for DR, DocumentReference, or Observation/Media
const resolveBinaryUrl = async (client, url) => {
    if (!url) return { url: "", contentType: null };

    if (
        url.startsWith("DocumentReference/") ||
        url.startsWith("DiagnosticReport/")
    ) {
        try {
            const resource = await client.request(url, {
                headers: { Accept: "application/fhir+json" }
            });

            if (resource.resourceType === "DocumentReference" && Array.isArray(resource.content)) {
                const attachment = resource.content[0]?.attachment;
                if (attachment?.url) return { url: attachment.url, contentType: attachment.contentType };
            }

            if (resource.resourceType === "DiagnosticReport" && Array.isArray(resource.presentedForm)) {
                const attachment = resource.presentedForm[0];
                if (attachment?.url) return { url: attachment.url, contentType: attachment.contentType };
            }
        } catch (err) {
            console.error("Error resolving binary from resource:", err);
        }
    }

    return { url, contentType: null };
};

// Open utility
const handleOpen = async (
    client,
    contentType,
    url,
    title,
    setModalSrc,
    setModalTitle,
    setModalType
) => {
    try {
        const { url: finalUrl, contentType: resolvedType } = await resolveBinaryUrl(client, url);
        const finalContentType = resolvedType || contentType || "application/octet-stream";

        const response = await client.request(finalUrl, {
            headers: { Accept: finalContentType },
            fetchResponse: true
        });

        let blob;
        if (!(response instanceof Response)) {
            const resource = response;
            if (resource.resourceType === "Binary" && resource.data) {
                const byteCharacters = atob(resource.data);
                const byteNumbers = new Array(byteCharacters.length);
                for (let i = 0; i < byteCharacters.length; i++)
                    byteNumbers[i] = byteCharacters.charCodeAt(i);

                blob = new Blob([new Uint8Array(byteNumbers)], {
                    type: resource.contentType || finalContentType
                });
            } else {
                blob = new Blob([JSON.stringify(resource, null, 2)], {
                    type: "application/json"
                });
            }
        } else {
            blob = await response.blob();
        }

        const blobUrl = window.URL.createObjectURL(blob);
        const extension = getExtensionFromContentType(finalContentType);

        let type = "generic";
        if (extension === "pdf") type = "pdf";
        else if (["jpg", "jpeg", "png", "gif", "bmp", "webp"].includes(extension)) type = "image";
        else if (["txt", "csv", "log"].includes(extension)) type = "text";
        else if (["html", "htm"].includes(extension)) type = "html";

        setModalSrc(blobUrl);
        setModalTitle(title);
        setModalType(type);
    } catch (error) {
        console.error("Open preview error:", error);
        setModalSrc("");
        setModalTitle(title);
        setModalType("generic");
    }
};

// ▶️ FINAL COMPONENT — preview-only version
const AttachmentPreview = ({ entry, fhirClient }) => {
    const [showModal, setShowModal] = useState(false);
    const [modalSrc, setModalSrc] = useState("");
    const [modalTitle, setModalTitle] = useState("");
    const [modalType, setModalType] = useState("generic");

    if (!entry) return <p>Select a document to preview.</p>;

    const resource = entry.resource;
    const sourceType = entry.sourceType;

    let attachments = [];

    if (sourceType === "DocumentReference")
        attachments = resource.content?.map((c) => c.attachment) || [];
    else if (sourceType === "DiagnosticReport")
        attachments = resource.presentedForm || [];
    else if (sourceType === "Observation" || sourceType === "Media") {
        attachments = resource.content
            ? Array.isArray(resource.content)
                ? resource.content
                : [resource.content]
            : [];
        if (sourceType === "Observation" && resource.valueAttachment)
            attachments.push(resource.valueAttachment);
    }

    const handleClose = () => {
        setShowModal(false);
        setModalSrc("");
        setModalTitle("");
        setModalType("generic");
    };

    return (
        <div className={styles.previewContainer}>
            <h6 className={styles.documentHeader}>Documents: {resource.id}</h6>

            {attachments.length > 0 ? (
                <div className="list-group mb-2">
                    {attachments.map((attachment, index) => {
                        const url = attachment.url;
                        const title = attachment.title || `Attachment ${index + 1}`;
                        const contentType = attachment.contentType || "application/octet-stream";

                        return (
                            <div
                                key={index}
                                className={`list-group-item d-flex flex-column ${styles.attachmentItem}`}
                            >
                                <div className={styles.attachmentRow}>
                                    {getIconForContentType(contentType, "Preview")}
                                    <span className={styles.title}>{title}</span>
                                </div>

                                <div className={styles.fileTypeLine}>
                                    Type: <span className={styles.fileType}>{sourceType}</span>
                                </div>

                                {attachment.creation && (
                                    <div className={styles.creation}>
                                        Created: {new Date(attachment.creation).toLocaleString()}
                                    </div>
                                )}

                                <div className={styles.linkRow}>
                                    <button
                                        onClick={() =>
                                            handleDownload(fhirClient, contentType, url, title)
                                        }
                                        className={styles.downloadLink}
                                    >
                                        Download
                                    </button>

                                    <button
                                        onClick={async () => {
                                            await handleOpen(
                                                fhirClient,
                                                contentType,
                                                url,
                                                title,
                                                setModalSrc,
                                                setModalTitle,
                                                setModalType
                                            );
                                            setShowModal(true);
                                        }}
                                        className={styles.openLink}
                                    >
                                        Open
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                </div>
            ) : (
                <p>No attachments found.</p>
            )}

            <Modal show={showModal} onHide={handleClose} size="xl" fullscreen="md-down" centered>
                <Modal.Header closeButton>
                    <Modal.Title>{modalTitle}</Modal.Title>
                </Modal.Header>
                <Modal.Body style={{ height: "80vh" }}>
                    {modalType === "pdf" && <PDFViewer blobUrl={modalSrc} />}
                    {modalType === "image" && (
                        <img
                            src={modalSrc}
                            alt={modalTitle}
                            style={{ maxWidth: "100%", maxHeight: "100%" }}
                        />
                    )}
                    {modalType === "text" && (
                        <iframe
                            src={modalSrc}
                            title={modalTitle}
                            style={{ width: "100%", height: "100%", border: "none" }}
                        />
                    )}
                    {modalType === "html" && (
                        <iframe
                            src={modalSrc}
                            title={modalTitle}
                            style={{ width: "100%", height: "100%", border: "none" }}
                        />
                    )}
                    {modalType === "generic" && (
                        <p className="text-muted text-center">
                            Preview not supported for this file type.
                        </p>
                    )}
                </Modal.Body>
            </Modal>
        </div>
    );
};

export default AttachmentPreview;
