import React, { useState } from "react";
import FemalePatient from "../assets/Patient_Female_96.png";
import MalePatient from "../assets/Patient_Male_96.png";
import styles from "./PatientCardExtended.module.css";


const calculateAge = (birthDate) => {
  if (!birthDate) return "";
  const dob = new Date(birthDate);
  const diff = Date.now() - dob.getTime();
  return new Date(diff).getUTCFullYear() - 1970;
};

const renderReference = (ref, name, onClick) => {
  if (!ref) return <span className="text-muted">N/A</span>;

  return name ? (
    <>
      {name}{" "}
      <button className="btn btn-link p-0" onClick={() => onClick?.(ref, name)}>
        ({ref})
      </button>
    </>
  ) : (
    <button className="btn btn-link p-0" onClick={() => onClick?.(ref, ref)}>
      {ref}
    </button>
  );
};

const PatientCardExtended = ({ resource, handleShowNested }) => {
  const fallbackUrl =
    resource.gender === "female"
      ? FemalePatient
      : resource.gender === "male"
        ? MalePatient
        : null;

  const initialPhotoUrl = resource.photo?.[0]?.url || fallbackUrl;
  const [imgSrc, setImgSrc] = useState(initialPhotoUrl);

  const officialName = resource.name?.find((n) => n.use === "official");
  const maidenName = resource.name?.find((n) => n.use === "maiden");
  const address = resource.address?.[0];
  const geo =
    address?.extension?.find((e) => e.url.includes("geolocation"))
      ?.extension || [];
  const race = resource.extension
    ?.find((e) => e.url.includes("us-core-race"))
    ?.valueCodeableConcept?.text;
  const ethnicity = resource.extension
    ?.find((e) => e.url.includes("us-core-ethnicity"))
    ?.valueCodeableConcept?.text;
  const birthPlace = resource.extension?.find((e) =>
    e.url.includes("birthPlace")
  )?.valueAddress;
  const mothersMaidenName = resource.extension?.find((e) =>
    e.url.includes("mothersMaidenName")
  )?.valueString;
  const deceased =
    resource.deceasedBoolean ?? resource.deceasedDateTime ?? null;

  const mrn = resource.identifier?.find((id) =>
    id.type?.coding?.some((c) => c.code === "MR")
  )?.value;

  return (
    <div>
      {/* Header */}
      <div className={styles.headerContainer}>
        <div className={styles.portraitWrapper}>
          <img
            src={imgSrc}
            alt="Patient Portrait"
            onError={() => {
              if (imgSrc !== fallbackUrl) setImgSrc(fallbackUrl);
            }}
            className={styles.portraitImage}
          />
        </div>

        <div>
          <h3 className="mb-1">
            {officialName?.prefix?.join(" ")} {officialName?.given?.join(" ")}{" "}
            {officialName?.family}
          </h3>

          {mrn && (
            <div className="mb-1 text-muted">
              <strong>MRN:</strong> {mrn}
            </div>
          )}

          {maidenName && (
            <div className="mb-1 text-muted">
              <strong>Maiden Name:</strong>{" "}
              {maidenName.given?.join(" ")} {maidenName.family}
            </div>
          )}

          <div className="mb-1 text-muted">
            <strong>DOB:</strong> {resource.birthDate} &nbsp;|&nbsp;
            <strong>Age:</strong> {calculateAge(resource.birthDate)}
          </div>

          <div className="mb-1 text-muted">
            <strong>Gender:</strong> {resource.gender}
          </div>

          {deceased && (
            <div className="mb-1 text-muted">
              <strong>Deceased:</strong> {String(deceased)}
            </div>
          )}
        </div>
      </div>

      {/* --- IDENTIFIERS --- */}
      <div className={styles.sectionHeader}>Identifiers</div>
      <div className="ps-5 pt-2">
        <div className="mb-1">
          <strong>Patient ID (CDR):</strong> {resource.id}
        </div>
        {resource.identifier?.map((id, idx) => (
          <div key={idx} className="mb-1">
            <strong>{id.type?.text || "Other"}:</strong> {id.value}
          </div>
        ))}
      </div>

      {/* --- CONTACT --- */}
      <div className={styles.sectionHeader}>Contact</div>
      <div className="ps-5 pt-2">
        {resource.contact?.map((c, idx) => (
          <div key={idx} className="mb-2">
            <strong>{c.relationship?.[0]?.text || "Contact"}:</strong>{" "}
            {c.name?.given?.join(" ")} {c.name?.family} ({c.gender})
            <div>
              <strong>Phone:</strong>{" "}
              {c.telecom?.find((t) => t.system === "phone")?.value}
            </div>
            {c.address && (
              <div>
                <strong>Address:</strong>{" "}
                {c.address.line?.join(", ")}, {c.address.city},{" "}
                {c.address.state} {c.address.postalCode},{" "}
                {c.address.country}
              </div>
            )}
          </div>
        ))}
      </div>

      {/* --- LOCATION --- */}
      <div className={styles.sectionHeader}>Location</div>
      <div className="ps-5 pt-2">
        {address && (
          <>
            <div className="mb-1">
              <strong>Address:</strong>{" "}
              {address.line?.join(", ")}, {address.city},{" "}
              {address.state} {address.postalCode}, {address.country}
              {geo.length > 0 && (
                <span className="text-muted">
                  {" "}
                  (Lat: {geo.find((e) => e.url === "latitude")?.valueDecimal},
                  Lon: {geo.find((e) => e.url === "longitude")?.valueDecimal})
                </span>
              )}
            </div>

            <div className="mb-1">
              <a
                href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(
                  `${address.line?.join(", ")}, ${address.city}, ${address.state
                  } ${address.postalCode}, ${address.country}`
                )}`}
                target="_blank"
                rel="noopener noreferrer"
              >
                View on Google Maps
              </a>
            </div>
          </>
        )}

        {birthPlace && (
          <div className="mb-1">
            <strong>Birthplace:</strong> {birthPlace.city},{" "}
            {birthPlace.state}, {birthPlace.country}
          </div>
        )}
      </div>

      {/* --- DEMOGRAPHICS --- */}
      <div className={styles.sectionHeader}>Demographics</div>
      <div className="ps-5 pt-2">
        <div className="mb-1">
          <strong>Race:</strong> {race || "Not provided"}
        </div>
        <div className="mb-1">
          <strong>Ethnicity:</strong> {ethnicity || "Not provided"}
        </div>
        <div className="mb-1">
          <strong>Marital Status:</strong> {resource.maritalStatus?.text}
        </div>
        <div className="mb-1">
          <strong>Multiple Birth:</strong>{" "}
          {resource.multipleBirthBoolean ? "Yes" : "No"}
        </div>
        {mothersMaidenName && (
          <div className="mb-1">
            <strong>Mother's Maiden Name:</strong> {mothersMaidenName}
          </div>
        )}
      </div>

      {/* --- LANGUAGE --- */}
      <div className={styles.sectionHeader}>Language</div>
      <div className="ps-5 pt-2">
        {resource.communication?.map((c, idx) => (
          <div key={idx} className="mb-1">
            <strong>Language:</strong> {c.language?.text}{" "}
            {c.preferred ? "(Preferred)" : ""}
          </div>
        ))}
      </div>

      {/* --- PROVIDERS --- */}
      <div className={styles.sectionHeader}>Providers</div>
      <div className="ps-5 pt-2">
        {resource.generalPractitioner?.map((gp, idx) => (
          <div key={idx} className="mb-1">
            <strong>General Practitioner:</strong>{" "}
            {renderReference(gp.reference, gp.display, handleShowNested)}
          </div>
        ))}
        {resource.managingOrganization && (
          <div className="mb-1">
            <strong>Managing Organization:</strong>{" "}
            {renderReference(
              resource.managingOrganization.reference,
              resource.managingOrganization.display,
              handleShowNested
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default PatientCardExtended;
