import { registerObservation } from "../slices/observationSlice";

/**
 * Fetch an Observation by ID
 * - Checks Redux store first
 * - Fetches from FHIR server if missing
 * - Registers into Redux
 */
export const fetchObservation = async (observationId, fhirClient, getState, dispatch) => {
    //console.log("fetching observation by id");
    if (!observationId || !fhirClient) return null;

    // Check Redux cache
    const cached = getState().observations?.[observationId];
    if (cached) {
        //console.log(`🧠 Observation ${observationId} served from cache`);
        return cached;
    }

    try {
        //console.log(`🌐 Fetching Observation/${observationId} from FHIR`);
        const fetched = await fhirClient.request(`Observation/${observationId}`);

        if (fetched?.resourceType !== "Observation") {
            console.warn("⚠️ Unexpected observation response:", fetched);
            return null;
        }

        dispatch(registerObservation(fetched));
        return fetched;

    } catch (err) {
        console.error("❌ Failed to fetch observation:", err);
        return null;
    }
};

/**
 * Fetch an Observation given a FHIR reference string
 * e.g. "Observation/123" or "Observation/123/_history/4"
 */
export const fetchObservationByReference = async (ref, fhirClient, getState, dispatch) => {
    //console.log("fetchin Observation by Reference....................");

    if (!ref || typeof ref !== "string") {
        console.warn("⚠️ Invalid observation reference (not a string):", ref);
        return null;
    }

    if (!ref.startsWith("Observation/")) {
        console.warn("⚠️ Reference is not an Observation:", ref);
        return null;
    }

    // Extract ID safely (handles versioned refs)
    // "Observation/123" → "123"
    // "Observation/123/_history/5" → "123"
    const parts = ref.split("/");
    const observationId = parts[1];

    if (!observationId || observationId === "undefined" || observationId === "null") {
        console.warn("⚠️ Could not extract valid observation ID from reference:", ref);
        return null;
    }

    return fetchObservation(observationId, fhirClient, getState, dispatch);
};
