// fetchAttachment.js
import { fetchBinaryBlob } from "./fetchBinaryBlob"; // adjust path as needed

/**
 * Fetch a FHIR attachment/resource safely.
 *
 * Supports:
 *  - External FHIR URLs (Binary, DocumentReference, Observation, etc)
 *  - Locally attached base64 files (no URL)
 *
 * @param {Object} attachmentRef - { url?, data?, contentType?, title? }
 * @param {Object} fhirClient - Initialized FHIR client with request()
 */
export const fetchAttachment = async (attachmentRef, fhirClient) => {
    console.log("fetchAttachment: starting fetch", attachmentRef);

    // ---------------------------------------------------------------------
    // 🆕 1. Handle locally-attached Base64 files (no URL → decode directly)
    // ---------------------------------------------------------------------
    if (!attachmentRef?.url && attachmentRef?.data) {
        console.log("fetchAttachment: Detected local base64 file, decoding directly");

        try {
            const byteCharacters = atob(attachmentRef.data);
            const byteNumbers = new Array(byteCharacters.length);

            for (let i = 0; i < byteCharacters.length; i++) {
                byteNumbers[i] = byteCharacters.charCodeAt(i);
            }

            const byteArray = new Uint8Array(byteNumbers);
            const blob = new Blob([byteArray], {
                type: attachmentRef.contentType || "application/octet-stream"
            });

            return {
                type: "LocalFile",
                title: attachmentRef.title || "file",
                contentType: attachmentRef.contentType,
                blob
            };
        } catch (err) {
            console.error("fetchAttachment: failed to decode base64 local file", err);
            return { error: "Failed to decode local base64 attachment" };
        }
    }

    // ---------------------------------------------------------------------
    // Original FHIR-based fetching
    // ---------------------------------------------------------------------
    if (!attachmentRef?.url) {
        console.warn("fetchAttachment: no URL in attachmentRef", attachmentRef);
        return { error: "No URL provided" };
    }

    const url = attachmentRef.url;
    console.log("fetchAttachment: fetching URL", url);

    try {
        const resource = await fhirClient.request(url);
        console.log("fetchAttachment: fetched resource type", resource?.resourceType, "id", resource?.id);

        if (!resource?.resourceType) {
            console.warn("fetchAttachment: resource has no type", resource);
            return { error: "Invalid resource fetched" };
        }

        // If URL looks like Binary but resource is not
        if (url.startsWith("Binary/") && resource.resourceType !== "Binary") {
            console.warn("fetchAttachment: URL suggests Binary but resourceType is", resource.resourceType);
        }

        switch (resource.resourceType) {
            case "Observation":
                return {
                    type: "Observation",
                    id: `Observation/${resource.id}`,
                    resource,
                    title: resource.code?.text || `Observation/${resource.id}`
                };

            case "DiagnosticReport":
                return {
                    type: "DiagnosticReport",
                    id: `DiagnosticReport/${resource.id}`,
                    resource,
                    title: resource.code?.text || `DiagnosticReport/${resource.id}`
                };

            case "DocumentReference": {
                const attachment =
                    resource.content?.[0]?.attachment ||
                    resource?.content?.attachment ||
                    resource.attachment ||
                    null;

                const title =
                    attachment?.title ||
                    resource.description ||
                    `DocumentReference/${resource.id}`;

                return {
                    type: "DocumentReference",
                    id: `DocumentReference/${resource.id}`,
                    resource,
                    title,
                    attachment,
                    contentType: attachment?.contentType,
                    url: attachment?.url || null,
                    data: attachment?.data || null
                };
            }

            case "Binary": {
                const blobRes = await fetchBinaryBlob(url, fhirClient);
                return {
                    type: "Binary",
                    id: resource.id,
                    blob: blobRes.blob,
                    contentType: blobRes.contentType,
                    title: blobRes.name || resource.id
                };
            }

            default: {
                const embedded =
                    resource?.content?.[0]?.attachment ||
                    resource?.presentedForm?.[0] ||
                    resource?.attachment;

                if (embedded) {
                    console.log("fetchAttachment: embedded attachment detected", embedded);
                }

                return {
                    type: resource.resourceType,
                    id: resource.id,
                    resource
                };
            }
        }
    } catch (err) {
        console.error("fetchAttachment: fetch failed for URL", url, err);
        return { error: `Fetch failed: ${err.message}` };
    }
};


/**
 * Fetch a Binary resource and return blob.
 */
export const fetchAttachmentBlob = async (binaryRef, fhirClient) => {
    try {
        if (!binaryRef) return { error: "No Binary reference provided." };
        console.log("fetchAttachmentBlob: Fetching Binary:", binaryRef);

        const blobRes = await fetchBinaryBlob(binaryRef, fhirClient);
        console.log("fetchAttachmentBlob: Fetched blob:", blobRes);

        return {
            type: "Binary",
            id: binaryRef,
            title: blobRes.name || binaryRef,
            contentType: blobRes.contentType,
            blob: blobRes.blob,
        };
    } catch (err) {
        console.error("fetchAttachmentBlob: Failed to fetch Binary:", binaryRef, err);
        return { error: `Binary fetch failed: ${err.message}` };
    }
};
